tionEnvironment.getExecutionEnvironment();\n        env.setParallelism(1);\n\n        DataStream<TaskEvent> tasks = env\n                .addSource(taskSourceOrTest(new GzTaskEventSource(taskInput)))\n                .returns(TypeInformation.of(TaskEvent.class))\n                .assignTimestampsAndWatermarks(\n                        WatermarkStrategy.<TaskEvent>forBoundedOutOfOrderness(Duration.ofSeconds(1))\n                                .withTimestampAssigner((e, t) -> e.getEventTimeMillis()));\n\n        DataStream<JobEvent> jobs = env\n                .addSource(jobSourceOrTest(new GzJobEventSource(jobInput)))\n                .returns(TypeInformation.of(JobEvent.class))\n                .assignTimestampsAndWatermarks(\n                        WatermarkStrategy.<JobEvent>forBoundedOutOfOrderness(Duration.ofSeconds(1))\n                                .withTimestampAssigner((e, t) -> e.getEventTimeMillis()));\n\n        TypeInformation<Tuple2<Long, Long>> tupleType =\n                TypeInformation.of(new TypeHint<Tuple2<Long, Long>>() {});\n\n        DataStream<Tuple2<Long, Long>> sessionCounts = tasks\n                .filter(e -> e.eventType == TaskEvent.SUBMIT)\n                .keyBy((TaskEvent e) -> e.jobId)\n                .window(EventTimeSessionWindows.withGap(Time.seconds(sesssize)))\n                .aggregate(new CountSubmitsAgg())\n                .returns(tupleType);\n\n        DataStream<Long> finishedJobs = jobs\n                .filter(e -> e.eventType == JobEvent.FINISH)\n                .map(e -> e.jobId)\n                .returns(TypeInformation.of(Long.class));\n\n        DataStream<Tuple2<Long, Long>> result = sessionCounts\n                .keyBy((Tuple2<Long, Long> t) -> t.f0)\n                .connect(finishedJobs.keyBy((Long id) -> id))\n                .process(new MaxPerJobCoProcess())\n                .returns(tupleType);\n\n        DataStream<String> output = result.map(t -> \"(\" + t.f0 + \",\" + t.f1 + \")\")\n               